1	//! The space collapsing infrastructure for realization.
2	
3	use typst_html::HtmlElem;
4	use typst_library::foundations::{Content, StyleChain};
5	use typst_library::introspection::TagElem;
6	use typst_library::layout::HElem;
7	use typst_library::routines::Pair;
8	use typst_library::text::{LinebreakElem, SmartQuoteElem, SpaceElem, TextElem};
9	
10	/// State kept for space collapsing.
11	#[derive(Debug, Copy, Clone, PartialEq, Eq)]
12	pub(crate) enum SpaceState {
13	    /// Invisible elements do not impact space collapsing.
14	    Invisible,
15	    /// Destructive elements discard spaces that come before or after.
16	    Destructive,
17	    /// Normal elements. Spaces are only kept if supported on both sides.
18	    Supportive,
19	    /// Adjacent spaces collapse as one with the styles of the first space.
20	    Space,
21	}
22	
23	/// Run the space collapsing algorithm on `buf[start..]`. This discards space
24	/// elements that are at the edges of the range or in the vicinity of
25	/// destructive elements and collapses adjacent spaces into one with the styles
26	/// of the first space.
27	///
28	/// This is implemented efficiently in-place by shifting elements in the buffer
29	/// to the left whenever we discard or collapse a space.
30	pub(crate) fn collapse_spaces(buf: &mut Vec<Pair>, start: usize) {
31	    let mut cursor = start;
32	    let mut prev_space = cursor;
33	    let mut state = SpaceState::Destructive;
34	
35	    // We do one pass over the elements, backshifting everything as necessary
36	    // when a space collapses. The variable `cursor` is our cursor in the
37	    // result. The variable `i` is our cursor in the original elements. At all
38	    // times, we have `cursor <= i`, so we can do it in-place.
39	    for i in start..buf.len() {
40	        let (content, styles) = buf[i];
41	
42	        state = match collapse_state(content, styles) {
43	            SpaceState::Invisible => state,
44	            SpaceState::Destructive => {
45	                if state == SpaceState::Space {
46	                    buf.copy_within(prev_space + 1..cursor, prev_space);
47	                    cursor -= 1;
48	                }
49	                SpaceState::Destructive
50	            }
51	            SpaceState::Supportive => SpaceState::Supportive,
52	            SpaceState::Space => {
53	                if state != SpaceState::Supportive {
54	                    continue;
55	                }
56	                prev_space = cursor;
57	                SpaceState::Space
58	            }
59	        };
60	
61	        // Copy over normal elements (in place).
62	        if cursor < i {
63	            buf[cursor] = buf[i];
64	        }
65	        cursor += 1;
66	    }
67	
68	    if state == SpaceState::Space {
69	        buf.copy_within(prev_space + 1..cursor, prev_space);
70	        cursor -= 1;
71	    }
72	
73	    // Delete all the excess that's left due to the gaps produced by spaces.
74	    buf.truncate(cursor);
75	}
76	
77	/// Space collapsing state for general elements.
78	pub(crate) fn collapse_state(content: &Content, styles: StyleChain) -> SpaceState {
79	    if content.is::<TagElem>() {
80	        SpaceState::Invisible
81	    } else if let Some(elem) = content.to_packed::<HElem>() {
82	        if elem.amount.is_fractional() || elem.weak.get(styles) {
83	            SpaceState::Destructive
84	        } else {
85	            SpaceState::Invisible
86	        }
87	    } else if content.is::<LinebreakElem>()
88	        // We want to collapse spaces that would otherwise be protected and show
89	        // up as spans with `white-space: pre-wrap`.
90	        || content.to_packed::<HtmlElem>().is_some_and(|elem| {
91	            typst_html::tag::is_whitespace_collapsing(elem.tag)
92	        })
93	    {
94	        SpaceState::Destructive
95	    } else if content.is::<SpaceElem>() {
96	        SpaceState::Space
97	    } else {
98	        SpaceState::Supportive
99	    }
100	}
101	
102	/// Space collapsing state for textual elements used during regex matching.
103	pub(crate) fn collapse_state_textual<'a>(
104	    content: &'a Content,
105	    styles: StyleChain<'_>,
106	) -> (SpaceState, &'a str) {
107	    if content.is::<TagElem>() {
108	        (SpaceState::Invisible, "")
109	    } else if content.is::<LinebreakElem>() {
110	        (SpaceState::Destructive, "\n")
111	    } else if content.is::<SpaceElem>() {
112	        (SpaceState::Space, " ")
113	    } else if let Some(elem) = content.to_packed::<TextElem>() {
114	        (SpaceState::Supportive, &elem.text)
115	    } else if let Some(elem) = content.to_packed::<SmartQuoteElem>() {
116	        let text = if elem.double.get(styles) { "\"" } else { "'" };
117	        (SpaceState::Supportive, text)
118	    } else {
119	        let name = content.elem().name();
120	        panic!("tried to find regex match in a non-textual element: {name}");
121	    }
122	}
