1	//! Typst's realization subsystem.
2	//!
3	//! *Realization* is the process of recursively applying styling and, in
4	//! particular, show rules to produce well-known elements that can be processed
5	//! further.
6	
7	use std::borrow::Cow;
8	use std::cell::LazyCell;
9	use std::slice::SliceIndex;
10	
11	use arrayvec::ArrayVec;
12	use bumpalo::Bump;
13	use bumpalo::collections::{CollectIn, String as BumpString, Vec as BumpVec};
14	use comemo::Track;
15	use ecow::EcoString;
16	use typst_html::HtmlElem;
17	use typst_library::diag::{At, SourceResult, bail, warning};
18	use typst_library::engine::Engine;
19	use typst_library::foundations::{
20	    Content, Context, ContextElem, Element, NativeElement, NativeShowRule, Packed,
21	    Recipe, RecipeIndex, Selector, SequenceElem, ShowSet, Style, StyleChain, StyledElem,
22	    Styles, SymbolElem, Synthesize, Target, TargetElem, Transformation,
23	};
24	use typst_library::introspection::{LocationKey, SplitLocator, Tag, TagElem, TagFlags};
25	use typst_library::layout::{
26	    AlignElem, BoxElem, HElem, InlineElem, PageElem, PagebreakElem, VElem,
27	};
28	use typst_library::math::{EquationElem, Mathy};
29	use typst_library::model::{
30	    CiteElem, CiteGroup, DocumentElem, EnumElem, ListElem, ListItemLike, ListLike,
31	    ParElem, ParbreakElem, TermsElem,
32	};
33	use typst_library::routines::{Arenas, FragmentKind, Pair, RealizationKind};
34	use typst_library::text::{LinebreakElem, SmartQuoteElem, SpaceElem, TextElem};
35	use typst_syntax::Span;
36	use typst_utils::{ListSet, SliceExt, SmallBitSet};
37	
38	mod spaces;
39	use spaces::{SpaceState, collapse_spaces, collapse_state_textual};
40	
41	/// Realize content into a flat list of well-known, styled items.
42	#[typst_macros::time(name = "realize")]
43	pub fn realize<'a>(
44	    kind: RealizationKind,
45	    engine: &mut Engine,
46	    locator: &mut SplitLocator,
47	    arenas: &'a Arenas,
48	    content: &'a Content,
49	    styles: StyleChain<'a>,
50	) -> SourceResult<Vec<Pair<'a>>> {
51	    let mut s = State {
52	        engine,
53	        locator,
54	        arenas,
55	        rules: match kind {
56	            RealizationKind::Bundle => BUNDLE_RULES,
57	            RealizationKind::Document { .. } => FLOW_RULES,
58	            RealizationKind::Fragment { .. } => FLOW_RULES,
59	            RealizationKind::Par => PAR_RULES,
60	            RealizationKind::Math => MATH_RULES,
61	        },
62	        sink: vec![],
63	        groupings: ArrayVec::new(),
64	        outside: matches!(kind, RealizationKind::Document { .. }),
65	        may_attach: false,
66	        saw_parbreak: false,
67	        kind,
68	    };
69	
70	    visit(&mut s, content, styles)?;
71	    finish(&mut s)?;
72	
73	    Ok(s.sink)
74	}
75	
76	/// Mutable state for realization.
77	///
78	/// Sadly, we need that many lifetimes because &mut references are invariant and
79	/// it would force the lifetimes of e.g. engine and locator to be equal if they
80	/// shared a lifetime. We can get around it by enforcing the lifetimes on
81	/// `fn realize`, but that makes it less flexible on the call site, which isn't
82	/// worth it.
83	///
84	/// The only interesting lifetime is 'a, which is that of the content that comes
85	/// in and goes out. It's the same 'a as on `fn realize`.
86	struct State<'a, 'x, 'y, 'z> {
87	    /// Defines what kind of realization we are performing.
88	    kind: RealizationKind<'x>,
89	    /// The engine.
90	    engine: &'x mut Engine<'y>,
91	    /// Assigns unique locations to elements.
92	    locator: &'x mut SplitLocator<'z>,
93	    /// Temporary storage arenas for lifetime extension during realization.
94	    arenas: &'a Arenas,
95	    /// The output elements of well-known types.
96	    sink: Vec<Pair<'a>>,
97	    /// Grouping rules used for realization.
98	    rules: &'x [&'x GroupingRule],
99	    /// Currently active groupings.
100	    groupings: ArrayVec<Grouping<'x>, MAX_GROUP_NESTING>,
101	    /// Whether we are currently not within any container or show rule output.
102	    /// This is used to determine page styles during layout.
103	    outside: bool,
104	    /// Whether now following attach spacing can survive.
105	    may_attach: bool,
106	    /// Whether we visited any paragraph breaks.
107	    saw_parbreak: bool,
108	}
109	
110	/// Defines a rule for how certain elements shall be grouped during realization.
111	struct GroupingRule {
112	    /// When an element is visited that matches a rule with higher priority
113	    /// than one that is currently grouped, we start a nested group.
114	    priority: u8,
115	    /// Whether the grouping handles tags itself. If this is set to `false`,
116	    /// realization will transparently take care of tags and they will not
117	    /// be visible to `finish`.
118	    tags: bool,
119	    /// Defines how the element relates to this kind of grouping.
120	    effect: fn(&Content) -> GroupingEffect,
121	    /// Defines whether styles for this kind of element interrupt the grouping.
122	    interrupt: fn(Element) -> bool,
123	    /// Should convert the accumulated elements in `s.sink[start..]` into
124	    /// the grouped element.
125	    finish: fn(Grouped) -> SourceResult<()>,
126	}
127	
128	/// Defines the effect of an element on a grouping.
129	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
130	enum GroupingEffect {
131	    /// The element will trigger this kind of grouping.
132	    Trigger,
133	    /// Defines elements that may appear in the interior of the grouping, but
134	    /// not at the edges. In particular, those elements also don't trigger the
135	    /// grouping.
136	    Inner,
137	    /// Defines elements that may appear intertwined with group elements without
138	    /// triggering finishing of the grouping. Once finishing is otherwise
139	    /// triggered, the neutral elements are segmented away and runs of other
140	    /// grouping elements are finished separately.
141	    ///
142	    /// The purpose of neutral elements is to allow for mixed flows of inline
143	    /// and blocky HTML elements (which is common in HTML).
144	    Neutral,
145	    /// The element will stop this kind of grouping.
146	    Interrupt,
147	}
148	
149	/// A started grouping of some elements.
150	struct Grouping<'a> {
151	    /// The position in `s.sink` where the group starts.
152	    start: usize,
153	    /// Only applies to `PAR` grouping: Whether this paragraph group is
154	    /// interrupted, but not yet finished because it may be ignored due to being
155	    /// fully inline.
156	    interrupted: bool,
157	    /// Whether the group contains neutral elements.
158	    contains_neutral: bool,
159	    /// The rule used for this grouping.
160	    rule: &'a GroupingRule,
161	}
162	
163	/// The result of grouping.
164	struct Grouped<'a, 'x, 'y, 'z, 's> {
165	    /// The realization state.
166	    s: &'s mut State<'a, 'x, 'y, 'z>,
167	    /// The position in `s.sink` where the group starts.
168	    start: usize,
169	}
170	
171	/// What to do with an element when encountering it during realization.
172	struct Verdict<'a> {
173	    /// Whether the element is already prepared (i.e. things that should only
174	    /// happen once have happened).
175	    prepared: bool,
176	    /// A map of styles to apply to the element.
177	    map: Styles,
178	    /// An optional show rule transformation to apply to the element.
179	    step: Option<ShowStep<'a>>,
180	}
181	
182	/// A show rule transformation to apply to the element.
183	enum ShowStep<'a> {
184	    /// A user-defined transformational show rule.
185	    Recipe(&'a Recipe, RecipeIndex),
186	    /// The built-in show rule.
187	    Builtin(NativeShowRule),
188	}
189	
190	/// A match of a regex show rule.
191	struct RegexMatch<'a> {
192	    /// The offset in the string that matched.
193	    offset: usize,
194	    /// The text that matched.
195	    text: EcoString,
196	    /// The style chain of the matching grouping.
197	    styles: StyleChain<'a>,
198	    /// The index of the recipe that matched.
199	    id: RecipeIndex,
200	    /// The recipe that matched.
201	    recipe: &'a Recipe,
202	}
203	
204	impl<'a> State<'a, '_, '_, '_> {
205	    /// Lifetime-extends some content.
206	    fn store(&self, content: Content) -> &'a Content {
207	        self.arenas.content.alloc(content)
208	    }
209	
210	    /// Lifetime-extends some pairs.
211	    ///
212	    /// By using a `BumpVec` instead of a `alloc_slice_copy` we can reuse
213	    /// the space if no other bump allocations have been made by the time
214	    /// the `BumpVec` is dropped.
215	    fn store_slice(&self, pairs: &[Pair<'a>]) -> BumpVec<'a, Pair<'a>> {
216	        let mut vec = BumpVec::new_in(&self.arenas.bump);
217	        vec.extend_from_slice_copy(pairs);
218	        vec
219	    }
220	}
221	
222	impl<'a, 'x, 'y, 'z, 's> Grouped<'a, 'x, 'y, 'z, 's> {
223	    /// Accesses the grouped elements.
224	    fn get(&self) -> &[Pair<'a>] {
225	        &self.s.sink[self.start..]
226	    }
227	
228	    /// Accesses the grouped elements mutably.
229	    fn get_mut(&mut self) -> (&mut Vec<Pair<'a>>, usize) {
230	        (&mut self.s.sink, self.start)
231	    }
232	
233	    /// Removes the grouped elements from the sink and retrieves back the state
234	    /// with which resulting elements can be visited.
235	    fn end(self) -> &'s mut State<'a, 'x, 'y, 'z> {
236	        self.s.sink.truncate(self.start);
237	        self.s
238	    }
239	}
240	
241	/// Handles an arbitrary piece of content during realization.
242	fn visit<'a>(
243	    s: &mut State<'a, '_, '_, '_>,
244	    content: &'a Content,
245	    styles: StyleChain<'a>,
246	) -> SourceResult<()> {
247	    // Tags can always simply be pushed.
248	    if content.is::<TagElem>() {
249	        s.sink.push((content, styles));
250	        return Ok(());
251	    }
252	
253	    // Transformations for content based on the realization kind. Needs
254	    // to happen before show rules.
255	    if visit_kind_rules(s, content, styles)? {
256	        return Ok(());
257	    }
258	
259	    // Apply show rules and preparation.
260	    if visit_show_rules(s, content, styles)? {
261	        return Ok(());
262	    }
263	
264	    // Recurse into sequences. Styled elements and sequences can currently also
265	    // have labels, so this needs to happen before they are handled.
266	    if let Some(sequence) = content.to_packed::<SequenceElem>() {
267	        for elem in &sequence.children {
268	            visit(s, elem, styles)?;
269	        }
270	        return Ok(());
271	    }
272	
273	    // Recurse into styled elements.
274	    if let Some(styled) = content.to_packed::<StyledElem>() {
275	        return visit_styled(s, &styled.child, Cow::Borrowed(&styled.styles), styles);
276	    }
277	
278	    // Apply grouping --- where multiple elements are collected and then
279	    // processed together (typically being transformed into one).
280	    if visit_grouping_rules(s, content, styles)? {
281	        return Ok(());
282	    }
283	
284	    // Some elements are skipped based on specific circumstances.
285	    if visit_filter_rules(s, content, styles)? {
286	        return Ok(());
287	    }
288	
289	    // No further transformations to apply, so we can finally just push it to
290	    // the output!
291	    s.sink.push((content, styles));
292	
293	    Ok(())
294	}
295	
296	// Handles transformations based on the realization kind.
297	fn visit_kind_rules<'a>(
298	    s: &mut State<'a, '_, '_, '_>,
299	    content: &'a Content,
300	    styles: StyleChain<'a>,
301	) -> SourceResult<bool> {
302	    if let RealizationKind::Math = s.kind {
303	        // Transparently recurse into equations nested in math, so that things
304	        // like this work:
305	        // ```
306	        // #let my = $pi$
307	        // $ my r^2 $
308	        // ```
309	        if let Some(elem) = content.to_packed::<EquationElem>() {
310	            visit(s, &elem.body, styles)?;
311	            return Ok(true);
312	        }
313	
314	        // In normal realization, we apply regex show rules to consecutive
315	        // textual elements via `TEXTUAL` grouping. However, in math, this is
316	        // not desirable, so we just do it on a per-element basis.
317	        if let Some(elem) = content.to_packed::<SymbolElem>() {
318	            if let Some(m) = find_regex_match_in_str(elem.text.as_str(), styles) {
319	                visit_regex_match(s, &[(content, styles)], m)?;
320	                return Ok(true);
321	            }
322	        } else if let Some(elem) = content.to_packed::<TextElem>()
323	            && let Some(m) = find_regex_match_in_str(&elem.text, styles)
324	        {
325	            visit_regex_match(s, &[(content, styles)], m)?;
326	            return Ok(true);
327	        }
328	    } else {
329	        // Transparently wrap mathy content into equations.
330	        if content.can::<dyn Mathy>() && !content.is::<EquationElem>() {
331	            let eq = EquationElem::new(content.clone()).pack().spanned(content.span());
332	            visit(s, s.store(eq), styles)?;
333	            return Ok(true);
334	        }
335	
336	        // Symbols in non-math content transparently convert to `TextElem` so we
337	        // don't have to handle them in non-math layout.
338	        if let Some(elem) = content.to_packed::<SymbolElem>() {
339	            let mut text = TextElem::packed(elem.text.clone()).spanned(elem.span());
340	            if let Some(label) = elem.label() {
341	                text.set_label(label);
342	            }
343	            visit(s, s.store(text), styles)?;
344	            return Ok(true);
345	        }
346	    }
347	
348	    Ok(false)
349	}
350	
351	/// Tries to apply show rules to or prepare content. Returns `true` if the
352	/// element was handled.
353	fn visit_show_rules<'a>(
354	    s: &mut State<'a, '_, '_, '_>,
355	    content: &'a Content,
356	    styles: StyleChain<'a>,
357	) -> SourceResult<bool> {
358	    // Determines whether and how to proceed with show rule application.
359	    let Some(Verdict { prepared, mut map, step }) = verdict(s.engine, content, styles)
360	    else {
361	        return Ok(false);
362	    };
363	
364	    // Create a fresh copy that we can mutate.
365	    let mut output = Cow::Borrowed(content);
366	
367	    // If the element isn't yet prepared (we're seeing it for the first time),
368	    // prepare it.
369	    let mut tags = None;
370	    if !prepared {
371	        tags = prepare(s.engine, s.locator, output.to_mut(), &mut map, styles)?;
372	    }
373	
374	    // Apply a show rule step, if there is one.
375	    if let Some(step) = step {
376	        let chained = styles.chain(&map);
377	        let result = match step {
378	            // Apply a user-defined show rule.
379	            ShowStep::Recipe(recipe, guard) => {
380	                let context = Context::new(output.location(), Some(chained));
381	                recipe.apply(
382	                    s.engine,
383	                    context.track(),
384	                    output.into_owned().guarded(guard),
385	                )
386	            }
387	
388	            // Apply a built-in show rule.
389	            ShowStep::Builtin(rule) => {
390	                let _scope = typst_timing::TimingScope::new(output.elem().name());
391	                rule.apply(&output, s.engine, chained)
392	                    .map(|content| content.spanned(output.span()))
393	            }
394	        };
395	
396	        // Errors in show rules don't terminate compilation immediately. We just
397	        // continue with empty content for them and show all errors together, if
398	        // they remain by the end of the introspection loop.
399	        //
400	        // This way, we can ignore errors that only occur in earlier iterations
401	        // and also show more useful errors at once.
402	        output = Cow::Owned(s.engine.delay(result));
403	    }
404	
405	    // Lifetime-extend the realized content if necessary.
406	    let realized = match output {
407	        Cow::Borrowed(realized) => realized,
408	        Cow::Owned(realized) => s.store(realized),
409	    };
410	
411	    // Push start tag.
412	    let (start, end) = tags.unzip();
413	    if let Some(tag) = start {
414	        visit(s, s.store(TagElem::packed(tag)), styles)?;
415	    }
416	
417	    let prev_outside = s.outside;
418	    s.outside &= content.is::<ContextElem>();
419	    s.engine.route.increase();
420	    s.engine.route.check_show_depth().at(content.span())?;
421	
422	    visit_styled(s, realized, Cow::Owned(map), styles)?;
423	
424	    s.outside = prev_outside;
425	    s.engine.route.decrease();
426	
427	    // Push end tag.
428	    if let Some(tag) = end {
429	        visit(s, s.store(TagElem::packed(tag)), styles)?;
430	    }
431	
432	    Ok(true)
433	}
