1001	/// The maximum number of nested groups that are possible. Corresponds to the
1002	/// number of unique priority levels.
1003	const MAX_GROUP_NESTING: usize = 3;
1004	
1005	/// Grouping rules used in bundle realization.
1006	static BUNDLE_RULES: &[&GroupingRule] = &[];
1007	
1008	/// Grouping rules used in normal realization.
1009	static FLOW_RULES: &[&GroupingRule] = &[&TEXTUAL, &PAR, &CITES, &LIST, &ENUM, &TERMS];
1010	
1011	/// Grouping rules used in paragraph realization.
1012	static PAR_RULES: &[&GroupingRule] = &[&TEXTUAL, &CITES, &LIST, &ENUM, &TERMS];
1013	
1014	/// Grouping rules used in math realization.
1015	static MATH_RULES: &[&GroupingRule] = &[&CITES, &LIST, &ENUM, &TERMS];
1016	
1017	/// Groups adjacent textual elements for text show rule application.
1018	static TEXTUAL: GroupingRule = GroupingRule {
1019	    priority: 3,
1020	    tags: true,
1021	    effect: |content| {
1022	        let elem = content.elem();
1023	        // Note that `SymbolElem` converts into `TextElem` before textual show
1024	        // rules run, and we apply textual rules to elements manually during
1025	        // math realization, so we don't check for it here.
1026	        if elem == TextElem::ELEM
1027	            || elem == LinebreakElem::ELEM
1028	            || elem == SmartQuoteElem::ELEM
1029	        {
1030	            GroupingEffect::Trigger
1031	        } else if elem == SpaceElem::ELEM {
1032	            GroupingEffect::Inner
1033	        } else {
1034	            GroupingEffect::Interrupt
1035	        }
1036	    },
1037	    // Any kind of style interrupts this kind of grouping since regex show
1038	    // rules cannot match over style changes anyway.
1039	    interrupt: |_| true,
1040	    finish: finish_textual,
1041	};
1042	
1043	/// Collects inline-level elements into a `ParElem`.
1044	static PAR: GroupingRule = GroupingRule {
1045	    priority: 1,
1046	    tags: true,
1047	    effect: |content| {
1048	        let elem = content.elem();
1049	        if elem == TextElem::ELEM
1050	            || elem == HElem::ELEM
1051	            || elem == LinebreakElem::ELEM
1052	            || elem == SmartQuoteElem::ELEM
1053	            || elem == InlineElem::ELEM
1054	            || elem == BoxElem::ELEM
1055	        {
1056	            GroupingEffect::Trigger
1057	        } else if elem == SpaceElem::ELEM {
1058	            GroupingEffect::Inner
1059	        } else if let Some(elem) = content.to_packed::<HtmlElem>() {
1060	            if typst_html::tag::should_group_into_pars(elem.tag) {
1061	                GroupingEffect::Trigger
1062	            } else {
1063	                GroupingEffect::Neutral
1064	            }
1065	        } else {
1066	            GroupingEffect::Interrupt
1067	        }
1068	    },
1069	    interrupt: |elem| elem == ParElem::ELEM || elem == AlignElem::ELEM,
1070	    finish: finish_par,
1071	};
1072	
1073	/// Collects `CiteElem`s into `CiteGroup`s.
1074	static CITES: GroupingRule = GroupingRule {
1075	    priority: 2,
1076	    tags: false,
1077	    effect: |content| {
1078	        let elem = content.elem();
1079	        if elem == CiteElem::ELEM {
1080	            GroupingEffect::Trigger
1081	        } else if elem == SpaceElem::ELEM {
1082	            GroupingEffect::Inner
1083	        } else {
1084	            GroupingEffect::Interrupt
1085	        }
1086	    },
1087	    interrupt: |elem| {
1088	        elem == CiteGroup::ELEM || elem == ParElem::ELEM || elem == AlignElem::ELEM
1089	    },
1090	    finish: finish_cites,
1091	};
1092	
1093	/// Builds a `ListElem` from grouped `ListItems`s.
1094	static LIST: GroupingRule = list_like_grouping::<ListElem>();
1095	
1096	/// Builds an `EnumElem` from grouped `EnumItem`s.
1097	static ENUM: GroupingRule = list_like_grouping::<EnumElem>();
1098	
1099	/// Builds a `TermsElem` from grouped `TermItem`s.
1100	static TERMS: GroupingRule = list_like_grouping::<TermsElem>();
1101	
1102	/// Collects `ListItemLike` elements into a `ListLike` element.
1103	const fn list_like_grouping<T: ListLike>() -> GroupingRule {
1104	    GroupingRule {
1105	        priority: 2,
1106	        tags: false,
1107	        effect: |content| {
1108	            let elem = content.elem();
1109	            if elem == T::Item::ELEM {
1110	                GroupingEffect::Trigger
1111	            } else if elem == SpaceElem::ELEM || elem == ParbreakElem::ELEM {
1112	                GroupingEffect::Inner
1113	            } else {
1114	                GroupingEffect::Interrupt
1115	            }
1116	        },
1117	        interrupt: |elem| elem == T::ELEM || elem == AlignElem::ELEM,
1118	        finish: finish_list_like::<T>,
1119	    }
1120	}
1121	
1122	/// Processes grouped textual elements.
1123	///
1124	/// Specifically, it searches for regex matches in grouped textual elements and
1125	/// - if there was a match, visits the results recursively,
1126	/// - if there was no match, tries to simply implicitly use the grouped elements
1127	///   as part of a paragraph grouping,
1128	/// - if that's not possible because another grouping is active, temporarily
1129	///   disables textual grouping and revisits the elements.
1130	fn finish_textual(Grouped { s, mut start }: Grouped) -> SourceResult<()> {
1131	    // Try to find a regex match in the grouped textual elements. Returns early
1132	    // if there is one.
1133	    if visit_textual(s, start)? {
1134	        return Ok(());
1135	    }
1136	
1137	    // There was no regex match, so we need to collect the text into a paragraph
1138	    // grouping. To do that, we first terminate all non-paragraph groupings.
1139	    if in_non_par_grouping(s) {
1140	        let elems = s.store_slice(&s.sink[start..]);
1141	        s.sink.truncate(start);
1142	        finish_grouping_while(s, in_non_par_grouping)?;
1143	        start = s.sink.len();
1144	        s.sink.extend(elems);
1145	    }
1146	
1147	    // Now, there are only two options:
1148	    // 1. We are already in a paragraph group. In this case, the elements just
1149	    //    transparently become part of it.
1150	    // 2. There is no group at all. In this case, we create one.
1151	    if s.groupings.is_empty() && s.rules.iter().any(|&rule| std::ptr::eq(rule, &PAR)) {
1152	        s.groupings.push(Grouping {
1153	            start,
1154	            rule: &PAR,
1155	            interrupted: false,
1156	            contains_neutral: false,
1157	        });
1158	    }
1159	
1160	    Ok(())
1161	}
1162	
1163	/// Whether there is an active grouping, but it is not a `PAR` grouping.
1164	fn in_non_par_grouping(s: &mut State) -> bool {
1165	    s.groupings.last().is_some_and(|grouping| {
1166	        !std::ptr::eq(grouping.rule, &PAR) || grouping.interrupted
1167	    })
1168	}
1169	
1170	/// Whether there is exactly one active grouping, it is a `PAR` grouping, and it
1171	/// spans the whole sink (with the exception of leading tags and neutral
1172	/// elements).
1173	fn is_fully_inline_or_neutral(s: &State) -> bool {
1174	    if let RealizationKind::Fragment { .. } = s.kind
1175	        && !s.saw_parbreak
1176	        && let [grouping] = s.groupings.as_slice()
1177	        && std::ptr::eq(grouping.rule, &PAR)
1178	        && s.sink[..grouping.start].iter().all(|(c, _)| {
1179	            c.is::<TagElem>() || (grouping.rule.effect)(c) == GroupingEffect::Neutral
1180	        })
1181	    {
1182	        true
1183	    } else {
1184	        false
1185	    }
1186	}
1187	
1188	/// Builds the `ParElem` from inline-level elements.
1189	fn finish_par(mut grouped: Grouped) -> SourceResult<()> {
1190	    // Collapse unsupported spaces in-place.
1191	    let (sink, start) = grouped.get_mut();
1192	    collapse_spaces(sink, start);
1193	
1194	    // Collect the children.
1195	    let elems = grouped.get();
1196	    let span = select_span(elems);
1197	    let (body, trunk) = repack(elems);
1198	
1199	    // Create and visit the paragraph.
1200	    let s = grouped.end();
1201	    let elem = ParElem::new(body).pack().spanned(span);
1202	    visit(s, s.store(elem), trunk)
1203	}
1204	
1205	/// Builds the `CiteGroup` from `CiteElem`s.
1206	fn finish_cites(grouped: Grouped) -> SourceResult<()> {
1207	    // Collect the children.
1208	    let elems = grouped.get();
1209	    let span = select_span(elems);
1210	    let trunk = elems[0].1;
1211	    let children = elems.iter().map(|(c, _)| (**c).clone()).collect();
1212	
1213	    // Create and visit the citation group.
1214	    let s = grouped.end();
1215	    let elem = CiteGroup::new(children).pack().spanned(span);
1216	    visit(s, s.store(elem), trunk)
1217	}
1218	
1219	/// Builds the `ListLike` element from `ListItemLike` elements.
1220	fn finish_list_like<T: ListLike>(grouped: Grouped) -> SourceResult<()> {
1221	    // Collect the children.
1222	    let elems = grouped.get();
1223	    let span = select_span(elems);
1224	    let tight = !elems.iter().any(|(c, _)| c.is::<ParbreakElem>());
1225	    let styles = elems.iter().filter(|(c, _)| c.is::<T::Item>()).map(|&(_, s)| s);
1226	    let trunk = StyleChain::trunk(styles).unwrap();
1227	    let trunk_depth = trunk.links().count();
1228	    let children = elems
1229	        .iter()
1230	        .copied()
1231	        .filter_map(|(c, s)| {
1232	            let item = c.to_packed::<T::Item>()?.clone();
1233	            let local = s.suffix(trunk_depth);
1234	            Some(T::Item::styled(item, local))
1235	        })
1236	        .collect();
1237	
1238	    // Create and visit the list.
1239	    let s = grouped.end();
1240	    let elem = T::create(children, tight).pack().spanned(span);
1241	    visit(s, s.store(elem), trunk)
1242	}
1243	
1244	/// Visit textual elements in `s.sink[start..]` and apply regex show rules to
1245	/// them.
1246	fn visit_textual(s: &mut State, start: usize) -> SourceResult<bool> {
1247	    // Try to find a regex match in the grouped textual elements.
1248	    if let Some(m) = find_regex_match_in_elems(s, &s.sink[start..]) {
1249	        collapse_spaces(&mut s.sink, start);
1250	        let elems = s.store_slice(&s.sink[start..]);
1251	        s.sink.truncate(start);
1252	        visit_regex_match(s, &elems, m)?;
1253	        return Ok(true);
1254	    }
1255	
1256	    Ok(false)
1257	}
1258	
1259	/// Finds the leftmost regex match for this style chain in the given textual
1260	/// elements.
1261	///
1262	/// Collects the element's merged textual representation into the bump arena.
1263	///
1264	/// This merging also takes into account space collapsing so that we don't need
1265	/// to call `collapse_spaces` on every textual group, performing yet another
1266	/// linear pass. We only collapse the space elements on the cold path when there
1267	/// is an actual match.
1268	fn find_regex_match_in_elems<'a>(
1269	    s: &State,
1270	    elems: &[Pair<'a>],
1271	) -> Option<RegexMatch<'a>> {
1272	    let mut buf = BumpString::new_in(&s.arenas.bump);
1273	    let mut base = 0;
1274	    let mut leftmost = None;
1275	    let mut current = StyleChain::default();
1276	    let mut state = SpaceState::Destructive;
1277	
1278	    for &(content, styles) in elems {
1279	        let (new_state, text) = collapse_state_textual(content, styles);
1280	        state = match new_state {
1281	            SpaceState::Invisible => continue,
1282	            SpaceState::Destructive => {
1283	                if state == SpaceState::Space {
1284	                    buf.pop();
1285	                }
1286	                SpaceState::Destructive
1287	            }
1288	            SpaceState::Supportive => SpaceState::Supportive,
1289	            SpaceState::Space => {
1290	                if state != SpaceState::Supportive {
1291	                    continue;
1292	                }
1293	                SpaceState::Space
1294	            }
1295	        };
1296	
1297	        // If styles differ, we search _before_ adding the new element's text.
1298	        if styles != current && !buf.is_empty() {
1299	            leftmost = find_regex_match_in_str(&buf, current);
1300	            if leftmost.is_some() {
1301	                break;
1302	            }
1303	            base += buf.len();
1304	            buf.clear();
1305	        }
1306	
1307	        current = styles;
1308	        buf.push_str(text);
1309	    }
1310	
1311	    if leftmost.is_none() {
1312	        leftmost = find_regex_match_in_str(&buf, current);
1313	    }
1314	
1315	    leftmost.map(|m| RegexMatch { offset: base + m.offset, ..m })
1316	}
1317	
1318	/// Finds the leftmost regex match for this style chain in the given text.
1319	fn find_regex_match_in_str<'a>(
1320	    text: &str,
1321	    styles: StyleChain<'a>,
1322	) -> Option<RegexMatch<'a>> {
1323	    let mut r = 0;
1324	    let mut revoked = SmallBitSet::new();
1325	    let mut leftmost: Option<(regex::Match, RecipeIndex, &Recipe)> = None;
1326	
1327	    let depth = LazyCell::new(|| styles.recipes().count());
1328	
1329	    for entry in styles.entries() {
1330	        let recipe = match &**entry {
1331	            Style::Recipe(recipe) => recipe,
1332	            Style::Property(_) => continue,
1333	            Style::Revocation(index) => {
1334	                revoked.insert(index.0);
1335	                continue;
1336	            }
1337	        };
1338	        r += 1;
1339	
1340	        let Some(Selector::Regex(regex)) = recipe.selector() else { continue };
1341	        let Some(m) = regex.find(text) else { continue };
1342	
1343	        // Make sure we don't get any empty matches.
1344	        if m.range().is_empty() {
1345	            continue;
1346	        }
1347	
1348	        // If we already have a match that is equally or more to the left, we're
1349	        // not interested in this new match.
1350	        if leftmost.is_some_and(|(p, ..)| p.start() <= m.start()) {
1351	            continue;
1352	        }
1353	
1354	        // Check whether the rule is already revoked. Do it only now to not
1355	        // compute the depth unnecessarily. We subtract 1 from r because we
1356	        // already incremented it.
1357	        let index = RecipeIndex(*depth - (r - 1));
1358	        if revoked.contains(index.0) {
1359	            continue;
1360	        }
1361	
1362	        leftmost = Some((m, index, recipe));
1363	    }
1364	
1365	    leftmost.map(|(m, id, recipe)| RegexMatch {
1366	        offset: m.start(),
1367	        text: m.as_str().into(),
1368	        id,
1369	        recipe,
1370	        styles,
1371	    })
1372	}
1373	
1374	/// Visit a regular expression match and any surrounding textual elements.
1375	///
1376	/// This will visit the following in order:
1377	/// - Elements that come fully before the match: `elem <match>`
1378	/// - Text that was interrupted by the start of the match: `te<match>`
1379	/// - The matched text itself, sliced off as a new element: `<match>`
1380	/// - Tag elements that come between parts of the match: `mat<tag>ch`
1381	/// - Text that was interrupted by the end of the match: `<match>xt`
1382	/// - Elements that come fully after the match: `<match> elem`
1383	///
1384	/// The matched text element will always be a `TextElem` or `SymbolElem` so that
1385	/// user code can rely on the element having a `.text` field to access the
1386	/// underlying string. If the regex matched only one existing text or symbol
1387	/// element, then the new element will be derived from that one, otherwise it
1388	/// will be built fresh with the span of the first matching element.
1389	fn visit_regex_match<'a>(
1390	    s: &mut State<'a, '_, '_, '_>,
1391	    elems: &[Pair<'a>],
1392	    m: RegexMatch<'a>,
1393	) -> SourceResult<()> {
1394	    let match_range = m.offset..m.offset + m.text.len();
1395	
1396	    let mut cursor = 0;
1397	    let mut m = Some(m);
1398	
1399	    for &(content, styles) in elems {
1400	        // Just forward tags. If a tag is between elements of the match, it will
1401	        // be visited immediately after the match.
1402	        if content.is::<TagElem>() {
1403	            visit(s, content, styles)?;
1404	            continue;
1405	        }
1406	
1407	        // At this point, we can have a `TextElem`, `SymbolElem`, `SpaceElem`,
1408	        // `LinebreakElem`, or `SmartQuoteElem`. We now determine the range of
1409	        // the element.
1410	        let len = if let Some(elem) = content.to_packed::<TextElem>() {
1411	            elem.text.len()
1412	        } else if let Some(elem) = content.to_packed::<SymbolElem>() {
1413	            elem.text.len()
1414	        } else {
1415	            1 // The rest are Ascii, so just one byte.
1416	        };
1417	        let elem_range = cursor..cursor + len;
1418	        cursor = elem_range.end;
1419	
1420	        if elem_range.end <= match_range.start || match_range.end <= elem_range.start {
1421	            // This element is entirely outside the matched range, visit it
1422	            // without slicing.
1423	            visit(s, content, styles)?;
1424	            continue;
1425	        }
1426	
1427	        if elem_range.start < match_range.start {
1428	            // This element's text begins before the start of the match, visit
1429	            // that initial part.
1430	            let end = match_range.start - elem_range.start;
1431	            visit(s, s.store(slice_textual(content, ..end)), styles)?;
1432	        }
1433	
1434	        // We visit the matched text itself when at the first element of the
1435	        // match. Note that we will effectively ignore the elements which
1436	        // compose the match.
1437	        if let Some(RegexMatch { text, styles, id, recipe, offset: _ }) = m.take() {
1438	            // Otherwise, we would have overlapped with a previous element.
1439	            debug_assert!(elem_range.start <= match_range.start);
1440	
1441	            let matched_text = if match_range.end <= elem_range.end
1442	                && (content.is::<TextElem>() || content.is::<SymbolElem>())
1443	            {
1444	                // If the match is fully contained within one sliceable element,
1445	                // we slice it to retain its element type and span/label.
1446	                slice_textual(
1447	                    content,
1448	                    match_range.start - elem_range.start
1449	                        ..match_range.end - elem_range.start,
1450	                )
1451	            } else {
1452	                // Otherwise we need to create a fresh text element and can only
1453	                // retain the span of the first matching element.
1454	                //
1455	                // Creating a text element instead of propagating the
1456	                // space/linebreak/smartquote ensures we always provide an
1457	                // element with a `.text` field, so that users can rely on that
1458	                // field being accessible.
1459	                TextElem::packed(text).spanned(content.span())
1460	            };
1461	
1462	            // Apply the show rule and visit the show rule's output element.
1463	            let context = Context::new(None, Some(styles));
1464	            let output = recipe.apply(s.engine, context.track(), matched_text)?;
1465	            let revocation = Style::Revocation(id).into();
1466	            let outer = s.arenas.bump.alloc(styles);
1467	            let chained = outer.chain(s.arenas.styles.alloc(revocation));
1468	            visit(s, s.store(output), chained)?;
1469	        }
1470	
1471	        if elem_range.end > match_range.end {
1472	            // This element's text finishes after the end of the match, visit
1473	            // that final part.
1474	            let start = match_range.end - elem_range.start;
1475	            visit(s, s.store(slice_textual(content, start..)), styles)?;
1476	        }
1477	    }
1478	
1479	    debug_assert!(m.is_none());
1480	    Ok(())
1481	}
1482	
1483	/// Takes a text or symbol element and returns an appropriate sliced output
1484	/// element.
1485	fn slice_textual(elem: &Content, range: impl SliceIndex<str, Output = str>) -> Content {
1486	    if let Some(elem) = elem.to_packed::<TextElem>() {
1487	        // Unfortunately, we can't apply a `TextElem::span_offset` for more
1488	        // precise tracking here because it creates a user-visible styled
1489	        // element, nesting the text element, and obscuring the `.text` field.
1490	        let mut elem = elem.clone();
1491	        elem.text = elem.text[range].into();
1492	        elem.pack()
1493	    } else if let Some(elem) = elem.to_packed::<SymbolElem>() {
1494	        // Symbols are also sliced despite being a single grapheme cluster for
1495	        // consistency with text. We may want to more generally avoid slicing
1496	        // grapheme clusters in the future.
1497	        // See also: <https://github.com/typst/typst/issues/8058>
1498	        let mut elem = elem.clone();
1499	        elem.text = elem.text[range].into();
1500	        elem.pack()
1501	    } else {
1502	        panic!("can only slice text and symbols");
1503	    }
1504	}
1505	
1506	/// Finds the first non-detached span in the list.
1507	fn select_span(children: &[Pair]) -> Span {
1508	    Span::find(children.iter().map(|(c, _)| c.span()))
1509	}
1510	
1511	/// Turn realized content with styles back into owned content and a trunk style
1512	/// chain.
1513	fn repack<'a>(buf: &[Pair<'a>]) -> (Content, StyleChain<'a>) {
1514	    let trunk = StyleChain::trunk_from_pairs(buf).unwrap_or_default();
1515	    let depth = trunk.links().count();
1516	
1517	    let mut seq = Vec::with_capacity(buf.len());
1518	
1519	    for (chain, group) in buf.group_by_key(|&(_, s)| s) {
1520	        let iter = group.iter().map(|&(c, _)| c.clone());
1521	        let suffix = chain.suffix(depth);
1522	        if suffix.is_empty() {
1523	            seq.extend(iter);
1524	        } else if let &[(element, _)] = group {
1525	            seq.push(element.clone().styled_with_map(suffix));
1526	        } else {
1527	            seq.push(Content::sequence(iter).styled_with_map(suffix));
1528	        }
1529	    }
1530	
1531	    (Content::sequence(seq), trunk)
1532	}
